void get_face_boundary_vertices(Triangulation::Face_handle face, int edge, std::list<Triangulation::Vertex_handle>& vertices) {
    // Check if the face has three vertices
    if (face->vertex(0) == face->vertex(1) || face->vertex(1) == face->vertex(2) || face->vertex(2) == face->vertex(0)) {
        return;
    }

    // Base case: if the face is already processed, return
    if (face->info().processed) {
        return;
    }

    // Mark the face as processed
    face->info().processed = true;

    // Get the vertices of the face
    Triangulation::Vertex_handle v1 = face->vertex((edge + 1) % 3);
    Triangulation::Vertex_handle v2 = face->vertex((edge + 2) % 3);

    // Check if the vertices are boundary vertices
    if (v1->info().has_point && v2->info().has_point) {
        // Add the vertices to the list if they are not already in the list
        if (std::find(vertices.begin(), vertices.end(), v1) == vertices.end()) {
            vertices.push_back(v1);
        }
        if (std::find(vertices.begin(), vertices.end(), v2) == vertices.end()) {
            vertices.push_back(v2);
        }
    }

    // Recursively call the function for the neighboring faces
    Triangulation::Face_handle neighbor = face->neighbor(edge);
    if (neighbor != Triangulation::Face_handle() && neighbor != face) {
        get_face_boundary_vertices(neighbor, (edge + 1) % 3, vertices);
    }
}
